const a = t(await callTool("item_create", { name: "a" }));
const b = t(await callTool("item_create", { name: "b", tag: "x" }));
console.log("ids:", a.item_id, b.item_id);

// update preserves unspecified fields
await callTool("item_update", { item_id: b.item_id, description: "d" });
const b2 = t(await callTool("item_get", { item_id: b.item_id }));
console.log("after update:", JSON.stringify(b2));

// list in creation order
const list = t(await callTool("item_list", {}));
console.log("list ids:", list.map(i => i.item_id).join(","));

// unknown tool rejected
try { await callTool("nope", {}); console.log("ERROR: should have thrown"); }
catch (e) { console.log("unknown tool error:", e.message); }

// invalid string validation
try { await callTool("item_create", { name: 123 }); console.log("ERROR: should have thrown"); }
catch (e) { console.log("invalid string error:", e.message); }

// additionalProperties:false in schema
const tools = await listTools();
console.log("all schemas have additionalProperties:false:", tools.every(x => x.inputSchema.additionalProperties === false));
